    // let teststrcte = silver_stream_dispatch_events | summarize arg_max(event_processed_utc_time,*) by event_id | where event_end_time > ago(7d) | order by event_end_time asc | limit 64 | summarize make_list(event_id);
    // let inputEventIds = toscalar(teststrcte);    let inputSiteIds = dynamic([]);
    // fxn start below
    let fxnToLoop = (inputEvent:string){ getSiteDispatchResults(inputEvent, inputSiteIds) };
    let fxn_wrapper = (T:(eventId:string)){ let singleEventId = toscalar(T | project eventId); fxnToLoop(singleEventId); };
    print eventId=inputEventIds
    | mv-expand with_itemindex=individualEvent eventId to typeof(string)
    | partition by individualEvent (invoke fxn_wrapper())
}
